 public sealed class PressMotion:MonoBehaviour,IPointerDownHandler,IPointerUpHandler,IPointerEnterHandler,IPointerExitHandler {
  float value=1,velocity,target=1;Vector3 position;bool held,hover;CraftedPanel frame;Color initial;Button button;
  void Awake(){position=transform.localPosition;frame=GetComponentInChildren<CraftedPanel>();if(frame)initial=frame.Fill;button=GetComponent<Button>();}
  bool Allowed=>!button||button.IsInteractable();
  public void OnPointerDown(PointerEventData e){if(!Allowed)return;held=true;FlatUI.LastPress=e.position;target=.91f;Studio.Sound?.Cue("press");}
  public void OnPointerUp(PointerEventData e){if(!held)return;held=false;target=1;velocity=1.65f;}
  public void OnPointerEnter(PointerEventData e){hover=true;}public void OnPointerExit(PointerEventData e){hover=false;if(held){held=false;target=1;}}
  void Update(){if(Studio.Profile?.ReducedMotion??false){transform.localScale=Vector3.one;if(frame)frame.Fill=held?Color.Lerp(initial,Color.white,.18f):initial;return;}float dt=Mathf.Min(.03f,Time.unscaledDeltaTime);velocity+=(target-value)*390*dt;velocity*=Mathf.Exp(-dt*20);value+=velocity*dt;transform.localScale=Vector3.one*value;if(frame){frame.Fill=Color.Lerp(initial,Color.white,held?.20f:hover&&Allowed?.08f:0);frame.Refresh();}}
 }
 public sealed class Soundtrack:MonoBehaviour {
  float duck;int cueStep;AudioSource music;readonly List<AudioSource> voices=new List<AudioSource>();Profile profile;int track=-1;
  public void Setup(Profile p){profile=p;music=gameObject.AddComponent<AudioSource>();music.loop=true;music.volume=.25f;for(int i=0;i<8;i++)voices.Add(gameObject.AddComponent<AudioSource>());PlayTrack(0);}
  public void PlayTrack(int index){if(track==index)return;track=index;music.clip=Resources.Load<AudioClip>("Audio/V4/music"+index)??Resources.Load<AudioClip>("Audio/music"+index);music.Play();Refresh();}
  public void Refresh(){if(music)music.mute=!profile.Music;}
  public void Cue(string name){if(profile==null)return;if(profile.Sound){bool important=name=="win"||name=="escape"||name=="result"||name=="alarm";AudioSource source=important?voices[0]:null;if(!important)for(int i=1;i<voices.Count;i++)if(!voices[i].isPlaying){source=voices[i];break;}if(source){if(important)source.Stop();source.pitch=(name=="cash"||name=="beat")?1+(cueStep++%5)*.055f:(name=="place"||name=="take")?UnityEngine.Random.Range(.96f,1.04f):1;source.volume=important?.68f:.48f;if(important)duck=1;source.PlayOneShot(Resources.Load<AudioClip>("Audio/V4/"+name)??Resources.Load<AudioClip>("Audio/"+name));}}
   if(profile.Haptics&&(name=="place"||name=="take")){
#if UNITY_ANDROID && !UNITY_EDITOR
    try{using(var player=new AndroidJavaClass("com.unity3d.player.UnityPlayer"))using(var activity=player.GetStatic<AndroidJavaObject>("currentActivity"))using(var vibrator=activity.Call<AndroidJavaObject>("getSystemService","vibrator"))using(var effects=new AndroidJavaClass("android.os.VibrationEffect"))using(var effect=effects.CallStatic<AndroidJavaObject>("createOneShot",12L,40))vibrator.Call("vibrate",effect);}catch(Exception){}
#endif
   }}
  void Update(){duck=Mathf.MoveTowards(duck,0,Time.unscaledDeltaTime*.7f);if(music)music.volume=Mathf.Lerp(.25f,.09f,duck);}
  void OnApplicationPause(bool value){if(value){if(music)music.Pause();}else if(music)music.UnPause();}
 }
